active_directory.template:
# Bulk Create AD Users from CSV
#Requires -Modules ActiveDirectory
$csv = Import-Csv '{{csv_path}}'
$securePass = ConvertTo-SecureString '{{initial_password}}' -AsPlainText -Force
foreach ($row in $csv) {
    $DisplayName = if ([string]::IsNullOrWhiteSpace($row.Surname)) { $row.GivenName } else { "$($row.GivenName) $($row.Surname)" }
    $params = @{
        Name = $DisplayName
        SamAccountName = $row.SamAccountName
        UserPrincipalName = $row.UserPrincipalName
        GivenName = $row.GivenName
        Surname = $row.Surname
        AccountPassword = $securePass
        Enabled = $true
    }
    if ($row.OU) { $params['Path'] = $row.OU }
    elseif ('{{ou_path}}') { $params['Path'] = '{{ou_path}}' }
    if ($row.Description) { $params['Description'] = $row.Description }
    New-ADUser @params
}

network_tools.template:
# Port Scan (common ports)
$ports = '{{port}}'
foreach ($p in $ports) {
    $result = Test-NetConnection -ComputerName '{{hostname}}' -Port $p -WarningAction SilentlyContinue -ErrorAction SilentlyContinue
    if ($result.TcpTestSucceeded) { Write-Host "Port $p - OPEN" -ForegroundColor Green } else { Write-Host "Port $p - Closed" -ForegroundColor Gray }
}

security.template:
# Event Log Hunter - Human-readable output
$idsRaw = '{{event_ids}}'.Trim()
if (-not $idsRaw) { Write-Warning 'Enter Event IDs or use a preset.'; exit 1 }
$ids = $idsRaw -split ',' | ForEach-Object { $t = $_.Trim(); if ($t) { [int]$t } } | Where-Object { $_ }
$start = (Get-Date).AddHours(-[int]'{{hours}}')

$eventNames = @{
  4624='Successful Logon'; 4625='Failed Logon'; 4634='Logoff'; 4648='RunAs Logon'
  4672='Admin Privileges Assigned'; 4673='Privilege Used'
  4720='User Account Created'; 4722='User Enabled'; 4724='Password Reset'; 4725='User Disabled'; 4726='User Deleted'; 4740='Account Locked Out'; 4767='Account Unlocked'
  4732='Member Added to Local Group'; 4733='Member Removed from Local Group'; 4728='Member Added to Global Group'; 4756='Member Added to Universal Group'
  4688='Process Created'; 4689='Process Terminated'
  4697='Service Installed'; 4698='Scheduled Task Created'; 4699='Scheduled Task Deleted'; 4702='Scheduled Task Updated'
  4616='System Time Changed'; 4719='Audit Policy Changed'; 4608='Windows Starting'
  6008='Unexpected Shutdown'; 1074='Shutdown Initiated'; 41='Kernel Power (unexpected loss)'
  4656='Object Handle Requested'; 4663='Object Accessed'; 4660='Object Deleted'
  1001='Blue Screen / WER'; 5140='Network Share Accessed'
}

try {
  $events = Get-WinEvent -FilterHashtable @{ LogName='{{log_name}}'; Id=$ids; StartTime=$start } -MaxEvents 5000 -ErrorAction Stop
  $count = $events.Count
  Write-Host "`n  Found $count event(s) in {{log_name}} (last {{hours}} hours)`n" -ForegroundColor Cyan

  $i = 1
  foreach ($e in $events) {
    $time = $e.TimeCreated.ToString('yyyy-MM-dd  HH:mm:ss')
    $name = if ($eventNames[$e.Id]) { " - $($eventNames[$e.Id])" } else { '' }
    Write-Host ('=' * 70) -ForegroundColor DarkGray
    Write-Host "  [$i]  $time" -ForegroundColor Gray
    Write-Host "  Event ID $($e.Id)$name" -ForegroundColor Cyan
    Write-Host "  Level: $($e.LevelDisplayName)" -ForegroundColor DarkYellow
    # Use only the first line (avoids the massive Subject:/Logon Info/etc. block)
    $raw = if ($e.Message) { $e.Message } else { '(no message)' }
    $lines = $raw -split "`r`n|`n"
    $summary = ($lines | Where-Object { $_.Trim().Length -gt 0 } | Select-Object -First 1)
    if (-not $summary) { $summary = $raw }
    $summary = ($summary -replace '\s+', ' ').Trim()
    if ($summary.Length -gt 350) { $summary = $summary.Substring(0,347) + '...' }
    Write-Host "  Summary: $summary" -ForegroundColor White
    Write-Host ""
    $i++
  }
  Write-Host ('=' * 70) -ForegroundColor DarkGray
  Write-Host "  End of report ($count event(s))`n" -ForegroundColor Cyan
} catch {
  if ($_.Exception.Message -match 'No events were found') {
    Write-Host "`n  No events found in the specified time range." -ForegroundColor Yellow
    Write-Host "  Try a longer time range, different Event IDs, or run as Administrator for Security log.`n" -ForegroundColor Gray
  } else { Write-Warning $_.Exception.Message }
}

# Last Logon Report
#Requires -Modules ActiveDirectory
$ou = '{{search_base}}'
if ($ou) { Get-ADUser -Filter * -SearchBase $ou -Properties LastLogonDate | Select-Object Name, SamAccountName, LastLogonDate | Sort-Object LastLogonDate -Descending | Format-Table -AutoSize }
else { Get-ADUser -Filter * -Properties LastLogonDate | Select-Object Name, SamAccountName, LastLogonDate | Sort-Object LastLogonDate -Descending | Format-Table -AutoSize }

system_maintenance.template:
# Check Critical Services
$svcs = '{{services}}' -split ',' | ForEach-Object { $_.Trim() }
foreach ($s in $svcs) {
    try {
        $svc = Get-Service -Name $s -ErrorAction Stop
        $status = if ($svc.Status -eq 'Running') { 'Running' } else { 'Stopped' }
        Write-Host "$s : $status"
    } catch { Write-Host "$s : Not Found" -ForegroundColor Yellow }
}

windows_updates.template:
# Uninstall Update by KB (run as Administrator)
$kb = ('{{kb_number}}' -replace 'KB','' -replace 'kb','').Trim()
if (-not $kb) { Write-Warning 'Enter a KB number (e.g. 5034441)'; exit 1 }
$packages = Get-WindowsPackage -Online -ErrorAction SilentlyContinue | Where-Object { $_.PackageName -like "*KB$kb*" }
if ($packages) {
  foreach ($p in $packages) {
    Write-Host "Removing: $($p.PackageName)" -ForegroundColor Yellow
    DISM /Online /Remove-Package /PackageName:$($p.PackageName) /NoRestart
  }
  Write-Host 'Done. Reboot may be required.' -ForegroundColor Green
} else { Write-Warning "No package found for KB$kb. It may not be installed or use different packaging." }

domain_migration.template:
# ==========================================================
# DOMAIN MIGRATION – SMART BACKUP + ONEDRIVE VALIDATION + BREAKGLASS
# ==========================================================

param(
    [string]$Destination = "{{Destination}}",
    [string]$BackupDesktop = "{{BackupDesktop}}",
    [string]$BackupDocuments = "{{BackupDocuments}}",
    [string]$BackupPictures = "{{BackupPictures}}",
    [string]$BackupDownloads = "{{BackupDownloads}}",
    [string]$BackupFavorites = "{{BackupFavorites}}",
    [string]$BackupLinks = "{{BackupLinks}}",
    [string]$BackupContacts = "{{BackupContacts}}",
    [string]$BackupSearches = "{{BackupSearches}}",
    [string]$BackupOutlook = "{{BackupOutlook}}",
    [string]$BackupChrome = "{{BackupChrome}}",
    [string]$BackupEdge = "{{BackupEdge}}",
    [string]$BackupFirefox = "{{BackupFirefox}}",
    [string]$BackupPrinters = "{{BackupPrinters}}"
)

# Fix unreplaced placeholders (when form fields left empty)
if ([string]::IsNullOrWhiteSpace($Destination) -or $Destination -match '^\{\{') { $Destination = '' }

trap {
    Write-Host "`n*** SCRIPT ERROR ***" -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red
    Read-Host "`nPress Enter to close"
    exit 1
}

Write-Host "=== DOMAIN MIGRATION SMART BACKUP STARTED ==="

if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]"Administrator")) {
    Write-Error "Run this script as Administrator."
    exit 1
}

# CREATE / VERIFY BREAKGLASS
$BreakGlassUserName   = "IT-BreakGlass"
$BreakGlassPlainPass  = "S0mething!VeryStr0ng#2026"
$BreakGlassSecurePass = ConvertTo-SecureString $BreakGlassPlainPass -AsPlainText -Force

try {
    $ExistingLocalUser = Get-LocalUser -Name $BreakGlassUserName -ErrorAction SilentlyContinue
    if (-not $ExistingLocalUser) {
        New-LocalUser -Name $BreakGlassUserName -Password $BreakGlassSecurePass -FullName "IT Emergency Admin" -Description "Local emergency admin" -PasswordNeverExpires:$true -UserMayNotChangePassword:$true -AccountNeverExpires:$true | Out-Null
    }
    elseif ($ExistingLocalUser.Enabled -eq $false) { Enable-LocalUser -Name $BreakGlassUserName }
    $IsBreakGlassAdmin = Get-LocalGroupMember -Group "Administrators" -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "*\$BreakGlassUserName" -or $_.Name -eq $BreakGlassUserName }
    if (-not $IsBreakGlassAdmin) { Add-LocalGroupMember -Group "Administrators" -Member $BreakGlassUserName }
} catch { Write-Error "Failed BreakGlass: $($_.Exception.Message)"; exit 1 }

# FUNCTIONS
function Test-ValidUserProfile { param([string]$Path)
    if (-not (Test-Path $Path)) { return $false }
    $Leaf = Split-Path $Path -Leaf
    $Excluded = @('Public','Default','Default User','All Users','Administrator','WDAGUtilityAccount')
    if ($Leaf -in $Excluded -or $Leaf -match '^TEMP\.') { return $false }
    return (Test-Path (Join-Path $Path 'NTUSER.DAT'))
}

function Get-TargetUserProfile {
    $CandidatePaths = [System.Collections.Generic.List[string]]::new()
    try { $LastUser = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI" -ErrorAction Stop).LastLoggedOnUser } catch { $LastUser = $null }
    if ($LastUser) {
        $UserPart = ($LastUser -split "\\")[-1]; if ($UserPart.StartsWith(".\")) { $UserPart = $UserPart.Substring(2) }
        if ($UserPart) { $CandidatePaths.Add("C:\Users\$UserPart") }
    }
    try {
        foreach ($p in Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList' -ErrorAction SilentlyContinue) {
            $pi = Get-ItemProperty $p.PSPath -ErrorAction SilentlyContinue
            if ($pi.ProfileImagePath -like 'C:\Users\*') {
                $exp = [Environment]::ExpandEnvironmentVariables($pi.ProfileImagePath)
                $CandidatePaths.Add($exp)
            }
        }
    } catch {}
    $Seen = @{}
    foreach ($Path in $CandidatePaths) {
        if ([string]::IsNullOrWhiteSpace($Path) -or $Seen[$Path.ToLower()]) { continue }
        $Seen[$Path.ToLower()] = $true
        if (Test-ValidUserProfile -Path $Path) {
            return [pscustomobject]@{ UserName = (Split-Path $Path -Leaf); ProfileDir = $Path }
        }
    }
    return $null
}

function Expand-UserPath { param([string]$PathValue, [string]$UserProfileDir = $null)
    if ([string]::IsNullOrWhiteSpace($PathValue)) { return $null }
    if ($UserProfileDir) { $PathValue = $PathValue -replace '%USERPROFILE%',$UserProfileDir -replace '\$env:USERPROFILE',$UserProfileDir }
    return [Environment]::ExpandEnvironmentVariables($PathValue)
}

function Invoke-RoboBackup { param([string]$Source, [string]$Destination)
    if (-not (Test-Path $Source)) { return }
    New-Item -ItemType Directory -Path $Destination -Force | Out-Null
    & robocopy $Source $Destination /E /COPY:DAT /R:1 /W:1 /NFL /NDL /NP /XJ | Out-Null
    if ($LASTEXITCODE -ge 8) { throw "Robocopy failed: $Source -> $Destination" }
}

# DETECT PROFILE
$ProfileInfo = Get-TargetUserProfile
if (-not $ProfileInfo) { Write-Error "No valid user profile found."; exit 1 }
$User = $ProfileInfo.UserName
$ProfileDir = $ProfileInfo.ProfileDir
$BackupRoot = if ($Destination -and $Destination -notmatch '^\{\{') { (Join-Path $Destination.TrimEnd('\') $User) } else { "C:\DomainMigration\$User" }
New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null

# Create BackupSummary early so restore can find this folder (even if script fails later)
"User: $User`nProfileDir: $ProfileDir`nBackupRoot: $BackupRoot`nComputerName: $env:COMPUTERNAME`nStarted: $(Get-Date)" | Out-File (Join-Path $BackupRoot "BackupSummary.txt") -Encoding UTF8 -Force

# RESOLVE SID (only needed for Desktop/Documents/Pictures - skip if printers-only)
$Sid = $null
$DesktopPath = Join-Path $ProfileDir 'Desktop'
$DocsPath = Join-Path $ProfileDir 'Documents'
$PicturesPath = Join-Path $ProfileDir 'Pictures'
$NeedUserPaths = ($BackupDesktop -eq 'true' -or $BackupDocuments -eq 'true' -or $BackupPictures -eq 'true')
if ($NeedUserPaths) {
    try { $Sid = (New-Object System.Security.Principal.NTAccount($User)).Translate([System.Security.Principal.SecurityIdentifier]).Value }
    catch { Write-Error "Could not resolve SID for $User"; exit 1 }
    $CurrentSid = ([Security.Principal.WindowsIdentity]::GetCurrent().User).Value
    $RunningAsSystem = ($CurrentSid -eq 'S-1-5-18')
    $UserShellKey = "Registry::HKEY_USERS\$Sid\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders"
    if (-not $RunningAsSystem -and (Test-Path $UserShellKey)) {
        try {
            $UShell = Get-ItemProperty $UserShellKey -ErrorAction Stop
            $DesktopPath = Expand-UserPath $UShell.Desktop -UserProfileDir $ProfileDir
            $DocsPath = Expand-UserPath $UShell.Personal -UserProfileDir $ProfileDir
            $PicturesPath = Expand-UserPath $UShell.'My Pictures' -UserProfileDir $ProfileDir
            if (-not $DesktopPath) { $DesktopPath = Join-Path $ProfileDir 'Desktop' }
            if (-not $DocsPath) { $DocsPath = Join-Path $ProfileDir 'Documents' }
            if (-not $PicturesPath) { $PicturesPath = Join-Path $ProfileDir 'Pictures' }
        } catch {
            $DesktopPath = Join-Path $ProfileDir 'Desktop'
            $DocsPath = Join-Path $ProfileDir 'Documents'
            $PicturesPath = Join-Path $ProfileDir 'Pictures'
        }
    }
}

# Check if folder is in OneDrive (already synced to cloud - skip backup)
function Test-OneDriveFolder { param([string]$Path) return $Path -and $Path -like '*OneDrive*' }

$BackupLog = [System.Collections.ArrayList]::new()

$DesktopInOD = Test-OneDriveFolder $DesktopPath
$DocsInOD = Test-OneDriveFolder $DocsPath
$PicturesInOD = Test-OneDriveFolder $PicturesPath

# CORE FOLDERS (Desktop, Documents, Pictures) - skip if in OneDrive
if ($BackupDesktop -eq 'true' -and (Test-Path $DesktopPath)) {
    if ($DesktopInOD) { Write-Host "Desktop in OneDrive - skipping (already in cloud)" -ForegroundColor Cyan; $BackupLog.Add("Desktop: SKIPPED (in OneDrive)") | Out-Null }
    else { Write-Host "Backing up Desktop..."; try { Invoke-RoboBackup -Source $DesktopPath -Destination (Join-Path $BackupRoot "Desktop"); $BackupLog.Add("Desktop: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("Desktop: FAILED - $($_.Exception.Message)") | Out-Null } }
}
if ($BackupDocuments -eq 'true' -and (Test-Path $DocsPath)) {
    if ($DocsInOD) { Write-Host "Documents in OneDrive - skipping (already in cloud)" -ForegroundColor Cyan; $BackupLog.Add("Documents: SKIPPED (in OneDrive)") | Out-Null }
    else { Write-Host "Backing up Documents..."; try { Invoke-RoboBackup -Source $DocsPath -Destination (Join-Path $BackupRoot "Documents"); $BackupLog.Add("Documents: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("Documents: FAILED - $($_.Exception.Message)") | Out-Null } }
}
if ($BackupPictures -eq 'true' -and (Test-Path $PicturesPath)) {
    if ($PicturesInOD) { Write-Host "Pictures in OneDrive - skipping (already in cloud)" -ForegroundColor Cyan; $BackupLog.Add("Pictures: SKIPPED (in OneDrive)") | Out-Null }
    else { Write-Host "Backing up Pictures..."; try { Invoke-RoboBackup -Source $PicturesPath -Destination (Join-Path $BackupRoot "Pictures"); $BackupLog.Add("Pictures: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("Pictures: FAILED - $($_.Exception.Message)") | Out-Null } }
}

# EXTRA FOLDERS - skip Downloads if in OneDrive
$ExtraMap = @{
    Downloads = @{ Backup = $BackupDownloads; Path = (Join-Path $ProfileDir 'Downloads') }
    Favorites = @{ Backup = $BackupFavorites; Path = (Join-Path $ProfileDir 'Favorites') }
    Links = @{ Backup = $BackupLinks; Path = (Join-Path $ProfileDir 'Links') }
    Contacts = @{ Backup = $BackupContacts; Path = (Join-Path $ProfileDir 'Contacts') }
    Searches = @{ Backup = $BackupSearches; Path = (Join-Path $ProfileDir 'Searches') }
}
foreach ($Folder in $ExtraMap.Keys) {
    $cfg = $ExtraMap[$Folder]
    if ($cfg.Backup -eq 'true' -and (Test-Path $cfg.Path)) {
        if ((Test-OneDriveFolder $cfg.Path)) { Write-Host "$Folder in OneDrive - skipping (already in cloud)" -ForegroundColor Cyan; $BackupLog.Add("$Folder`: SKIPPED (in OneDrive)") | Out-Null }
        else { Write-Host "Backing up $Folder..."; try { Invoke-RoboBackup -Source $cfg.Path -Destination (Join-Path $BackupRoot $Folder); $BackupLog.Add("$Folder`: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("$Folder`: FAILED - $($_.Exception.Message)") | Out-Null } }
    }
}

# OUTLOOK
if ($BackupOutlook -eq 'true') {
    $Outlook = Join-Path $ProfileDir "AppData\Roaming\Microsoft\Outlook"
    if (Test-Path $Outlook) { Write-Host "Backing up Outlook..."; try { Invoke-RoboBackup -Source $Outlook -Destination (Join-Path $BackupRoot "Outlook"); $BackupLog.Add("Outlook: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("Outlook: FAILED - $($_.Exception.Message)") | Out-Null } }
}
# BROWSERS
if ($BackupChrome -eq 'true') {
    $Chrome = Join-Path $ProfileDir "AppData\Local\Google\Chrome\User Data"
    if (Test-Path $Chrome) { Write-Host "Backing up Chrome..."; try { Invoke-RoboBackup -Source $Chrome -Destination (Join-Path $BackupRoot "Chrome"); $BackupLog.Add("Chrome: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("Chrome: FAILED - $($_.Exception.Message)") | Out-Null } }
}
if ($BackupEdge -eq 'true') {
    $Edge = Join-Path $ProfileDir "AppData\Local\Microsoft\Edge\User Data"
    if (Test-Path $Edge) { Write-Host "Backing up Edge..."; try { Invoke-RoboBackup -Source $Edge -Destination (Join-Path $BackupRoot "Edge"); $BackupLog.Add("Edge: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("Edge: FAILED - $($_.Exception.Message)") | Out-Null } }
}
if ($BackupFirefox -eq 'true') {
    $Firefox = Join-Path $ProfileDir "AppData\Roaming\Mozilla"
    if (Test-Path $Firefox) { Write-Host "Backing up Firefox..."; try { Invoke-RoboBackup -Source $Firefox -Destination (Join-Path $BackupRoot "Firefox"); $BackupLog.Add("Firefox: BACKED UP") | Out-Null } catch { Write-Warning $_.Exception.Message; $BackupLog.Add("Firefox: FAILED - $($_.Exception.Message)") | Out-Null } }
}

# PRINTERS - full backup with PrintBrm (drivers, ports, printers) for restore
if ($BackupPrinters -eq 'true') {
    $PrinterDir = Join-Path $BackupRoot "Printers"
    New-Item -ItemType Directory -Path $PrinterDir -Force | Out-Null
    try {
        Import-Module PrintManagement -ErrorAction Stop
        $Printers = Get-Printer -ErrorAction SilentlyContinue | Sort-Object Name
        if ($Printers.Count -eq 0) {
            Write-Host "No printers found on this system." -ForegroundColor Yellow
            $BackupLog.Add("Printers: SKIPPED (none found)") | Out-Null
        } else {
            Write-Host "Found $($Printers.Count) printer(s): $($Printers.Name -join ', ')"
            $Default = ($Printers | Where-Object Default | Select-Object -First 1).Name
            $PrintersList = @()
            foreach ($p in $Printers) {
                $PortInfo = $null
                try { $PortInfo = Get-PrinterPort -Name $p.PortName -ErrorAction SilentlyContinue } catch {}
                $pi = @{ Name=$p.Name; DriverName=$p.DriverName; PortName=$p.PortName; IsDefault=($p.Name -eq $Default) }
                if ($PortInfo -and $PortInfo.PrinterHostAddress) { $pi.PortAddress = $PortInfo.PrinterHostAddress }
                $PrintersList += [pscustomobject]$pi
            }
            $Ports = Get-PrinterPort -ErrorAction SilentlyContinue
            $Drivers = Get-PrinterDriver -ErrorAction SilentlyContinue
            @{ ComputerName=$env:COMPUTERNAME; CollectedAt=(Get-Date).ToString("s"); Printers=$PrintersList; Ports=$Ports; Drivers=$Drivers } | ConvertTo-Json -Depth 6 | Out-File (Join-Path $PrinterDir "Printers.json") -Encoding UTF8

            $PrintBrmPath = Join-Path $env:SystemRoot "System32\spool\tools\printbrm.exe"
            $ExportPath = Join-Path $PrinterDir "Printers.printerExport"
            if (Test-Path $PrintBrmPath) {
                Write-Host "Backing up printers (PrintBrm) - drivers, ports, queues..."
                try {
                    $pinfo = New-Object System.Diagnostics.ProcessStartInfo
                    $pinfo.FileName = $PrintBrmPath
                    $pinfo.Arguments = "-b -s \\$env:COMPUTERNAME -f `"$ExportPath`""
                    $pinfo.RedirectStandardError = $true
                    $pinfo.RedirectStandardOutput = $true
                    $pinfo.UseShellExecute = $false
                    $p = New-Object System.Diagnostics.Process
                    $p.StartInfo = $pinfo
                    $p.Start() | Out-Null
                    $out = $p.StandardOutput.ReadToEnd()
                    $err = $p.StandardError.ReadToEnd()
                    $p.WaitForExit()
                    if ($p.ExitCode -ne 0 -or -not (Test-Path $ExportPath)) {
                        Write-Warning "PrintBrm exit code: $($p.ExitCode). Printers.json saved - use for manual restore."
                        if ($err) { Write-Host $err -ForegroundColor Yellow }
                    } else {
                        Write-Host "Printer backup complete: $ExportPath" -ForegroundColor Green
                    }
                } catch {
                    Write-Warning "PrintBrm failed: $($_.Exception.Message). Printers.json saved for reference."
                }
                if (-not (Test-Path $ExportPath)) {
                    Write-Host "Exporting printer drivers only (PrintBrm fallback)..."
                    $DriversDir = Join-Path $PrinterDir "Drivers"
                    New-Item -ItemType Directory -Path $DriversDir -Force | Out-Null
                    $UsedDrivers = $PrintersList | Select-Object -ExpandProperty DriverName -Unique
                    foreach ($dName in $UsedDrivers) {
                        $drv = Get-PrinterDriver -Name $dName -ErrorAction SilentlyContinue
                        if ($drv -and $drv.InfPath -and $drv.Manufacturer -notmatch 'Microsoft') {
                            $src = Split-Path $drv.InfPath -Parent
                            if (Test-Path $src) {
                                $dest = Join-Path $DriversDir ($dName -replace '[\\/:*?"<>|]','_')
                                New-Item $dest -ItemType Directory -Force | Out-Null
                                Copy-Item "$src\*" $dest -Recurse -Force -ErrorAction SilentlyContinue
                            }
                        }
                    }
                }
            } else {
                Write-Warning "PrintBrm not found. Exporting printer drivers only."
                $DriversDir = Join-Path $PrinterDir "Drivers"
                New-Item -ItemType Directory -Path $DriversDir -Force | Out-Null
                $UsedDrivers = $PrintersList | Select-Object -ExpandProperty DriverName -Unique
                foreach ($dName in $UsedDrivers) {
                    $drv = Get-PrinterDriver -Name $dName -ErrorAction SilentlyContinue
                    if ($drv -and $drv.InfPath -and $drv.Manufacturer -notmatch 'Microsoft') {
                        $src = Split-Path $drv.InfPath -Parent
                        if (Test-Path $src) {
                            $dest = Join-Path $DriversDir ($dName -replace '[\\/:*?"<>|]','_')
                            New-Item $dest -ItemType Directory -Force | Out-Null
                            Copy-Item "$src\*" $dest -Recurse -Force -ErrorAction SilentlyContinue
                        }
                    }
                }
            }
            $BackupLog.Add("Printers: BACKED UP ($($Printers.Count) printer(s) - $($Printers.Name -join ', '))") | Out-Null
        }
    } catch { Write-Warning "Printer backup failed: $($_.Exception.Message)"; $BackupLog.Add("Printers: FAILED - $($_.Exception.Message)") | Out-Null }
}

# SUMMARY
$TotalItems = (Get-ChildItem $BackupRoot -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object).Count
$LogSection = if ($BackupLog.Count -gt 0) { "`n--- BACKUP LOG ---`n" + ($BackupLog -join "`n") } else { "" }
$Summary = "User: $User`nProfileDir: $ProfileDir`nSID: $Sid`nBackupRoot: $BackupRoot`nTotalItems: $TotalItems`nComputerName: $env:COMPUTERNAME`nExecutedAs: $([System.Security.Principal.WindowsIdentity]::GetCurrent().Name)`nCompleted: $(Get-Date)$LogSection"
$Summary | Out-File (Join-Path $BackupRoot "BackupSummary.txt") -Encoding UTF8
New-Item (Join-Path $BackupRoot "BACKUP_COMPLETED.txt") -ItemType File -Force | Out-Null
Write-Host "=== DOMAIN MIGRATION BACKUP COMPLETED ===" -ForegroundColor Green
Write-Host "Backup location: $BackupRoot"
Read-Host "`nPress Enter to close"

# ==========================================================
# DOMAIN MIGRATION – RESTORE SCRIPT
# Auto-detects what was backed up and restores it (no checkboxes)
# ==========================================================

param(
    [string]$Source = "{{Source}}",
    [string]$UserName = "{{UserName}}",
    [string]$TargetProfilePath = "{{TargetProfilePath}}"
)

# Fix unreplaced placeholders
if ($Source -match '^\{\{') { $Source = '' }
if ($UserName -match '^\{\{') { $UserName = '' }
if ($TargetProfilePath -match '^\{\{') { $TargetProfilePath = '' }

trap {
    Write-Host "`n*** SCRIPT ERROR ***" -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red
    Write-Host $_.ScriptStackTrace -ForegroundColor Gray
    Read-Host "`nPress Enter to close"
    exit 1
}

Write-Host "=== DOMAIN MIGRATION RESTORE STARTED ==="

if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]"Administrator")) {
    Write-Error "Run this script as Administrator."
    Read-Host "Press Enter to close"
    exit 1
}

function Test-ValidUserProfile { param([string]$Path)
    if (-not (Test-Path $Path)) { return $false }
    $Leaf = Split-Path $Path -Leaf
    $Excluded = @('Public','Default','Default User','All Users','Administrator','WDAGUtilityAccount')
    if ($Leaf -in $Excluded -or $Leaf -match '^TEMP\.') { return $false }
    return (Test-Path (Join-Path $Path 'NTUSER.DAT'))
}

function Get-TargetUserProfile { param([string]$PreferUserName = $null)
    $CandidatePaths = [System.Collections.Generic.List[string]]::new()
    if ($PreferUserName) { $CandidatePaths.Add("C:\Users\$PreferUserName") }
    try {
        $LastUser = (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI" -ErrorAction Stop).LastLoggedOnUser
        if ($LastUser) {
            $UserPart = ($LastUser -split "\\")[-1]
            if ($UserPart.StartsWith(".\")) { $UserPart = $UserPart.Substring(2) }
            if ($UserPart -and ("C:\Users\$UserPart" -notin $CandidatePaths)) { $CandidatePaths.Add("C:\Users\$UserPart") }
        }
    } catch {}
    try {
        foreach ($p in (Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList' -ErrorAction SilentlyContinue)) {
            $pi = Get-ItemProperty $p.PSPath -ErrorAction SilentlyContinue
            if ($pi.ProfileImagePath -like 'C:\Users\*') {
                $exp = [Environment]::ExpandEnvironmentVariables($pi.ProfileImagePath)
                if ($exp -notin $CandidatePaths) { $CandidatePaths.Add($exp) }
            }
        }
    } catch {}
    $Seen = @{}
    foreach ($Path in $CandidatePaths) {
        if ([string]::IsNullOrWhiteSpace($Path) -or $Seen[$Path.ToLower()]) { continue }
        $Seen[$Path.ToLower()] = $true
        if (Test-ValidUserProfile -Path $Path) {
            return [pscustomobject]@{ UserName = (Split-Path $Path -Leaf); ProfileDir = $Path }
        }
    }
    return $null
}

function Expand-UserPath { param([string]$PathValue, [string]$UserProfileDir = $null)
    if ([string]::IsNullOrWhiteSpace($PathValue)) { return $null }
    if ($UserProfileDir) { $PathValue = $PathValue -replace '%USERPROFILE%',$UserProfileDir -replace '\$env:USERPROFILE',$UserProfileDir }
    return [Environment]::ExpandEnvironmentVariables($PathValue)
}

function Invoke-RoboRestore { param([string]$Source, [string]$Destination)
    if (-not (Test-Path $Source)) { return }
    New-Item -ItemType Directory -Path $Destination -Force | Out-Null
    & robocopy $Source $Destination /E /COPY:DAT /R:1 /W:1 /NFL /NDL /NP /IS /IT | Out-Null
    if ($LASTEXITCODE -ge 8) { Write-Warning "Robocopy reported issues (exit $LASTEXITCODE)" }
    else { Write-Host "Restored: $Destination" }
}

# DETECT TARGET PROFILE
$ProfileInfo = if ($TargetProfilePath -and (Test-ValidUserProfile $TargetProfilePath)) {
    [pscustomobject]@{ UserName = (Split-Path $TargetProfilePath -Leaf); ProfileDir = $TargetProfilePath }
} else {
    Get-TargetUserProfile -PreferUserName $UserName
}

if (-not $ProfileInfo) {
    Write-Error "No valid target user profile found. User may need to log on once."
    Read-Host "Press Enter to close"
    exit 1
}

$ProfileDir = $ProfileInfo.ProfileDir
$User = $ProfileInfo.UserName

Write-Host "Detected user: $User"
Write-Host "Using profile: $ProfileDir"

# FIND BACKUP
$BackupRoot = $null
$SearchRoots = @()
if ($Source) {
    $SearchRoots = @($Source.TrimEnd('\'))
} else {
    $SearchRoots = @("C:\DomainMigration", "C:\Backup")
    foreach ($d in @("D:\DomainMigration", "D:\Backup", "E:\DomainMigration", "E:\Backup")) {
        if (Test-Path $d) { $SearchRoots += $d }
    }
}

$IsValidBackup = { param($p) (Test-Path (Join-Path $p "BackupSummary.txt")) -or (Test-Path (Join-Path $p "Printers\Printers.json")) -or (Test-Path (Join-Path $p "Printers\Printers.printerExport")) }
foreach ($MigrationRoot in $SearchRoots) {
    if (-not (Test-Path $MigrationRoot)) { continue }
    if (& $IsValidBackup $MigrationRoot) { $BackupRoot = $MigrationRoot; break }
    $ProfileLeaf = Split-Path $ProfileDir -Leaf
    foreach ($candidate in @($ProfileLeaf, ($ProfileLeaf -replace '\..*$',''), $UserName, "user", "User")) {
        if (-not $candidate) { continue }
        $candidatePath = Join-Path $MigrationRoot $candidate
        if (& $IsValidBackup $candidatePath) { $BackupRoot = $candidatePath; break }
    }
    if ($BackupRoot) { break }
    $Found = Get-ChildItem $MigrationRoot -Directory -ErrorAction SilentlyContinue | Where-Object {
        & $IsValidBackup $_.FullName
    } | Select-Object -First 1
    if ($Found) { $BackupRoot = $Found.FullName; break }
}

if (-not $BackupRoot -or -not (Test-Path $BackupRoot)) {
    Write-Host "`nBackup not found. Searched:" -ForegroundColor Yellow
    foreach ($r in $SearchRoots) { Write-Host "  - $r" -ForegroundColor Gray }
    Write-Host "`nEnter the full path to your backup folder in the Source field." -ForegroundColor Yellow
    Write-Host "Example: C:\DomainMigration\YourUsername  or  C:\Backup\YourUsername" -ForegroundColor Gray
    Write-Host "The folder must contain BackupSummary.txt" -ForegroundColor Gray
    Read-Host "`nPress Enter to close"
    exit 1
}

Write-Host "Restoring from: $BackupRoot"

# RESOLVE SID AND USER SHELL FOLDERS (for Desktop, Documents, Pictures)
$Sid = $null
try { $Sid = (New-Object System.Security.Principal.NTAccount($User)).Translate([System.Security.Principal.SecurityIdentifier]).Value } catch {}
$CurrentSid = ([Security.Principal.WindowsIdentity]::GetCurrent().User).Value
$RunningAsSystem = ($CurrentSid -eq 'S-1-5-18')

$DesktopPath = Join-Path $ProfileDir 'Desktop'
$DocsPath = Join-Path $ProfileDir 'Documents'
$PicturesPath = Join-Path $ProfileDir 'Pictures'

if (-not $RunningAsSystem -and $Sid -and (Test-Path "Registry::HKEY_USERS\$Sid\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders")) {
    try {
        $UShell = Get-ItemProperty "Registry::HKEY_USERS\$Sid\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders" -ErrorAction Stop
        $DesktopPath = Expand-UserPath $UShell.Desktop -UserProfileDir $ProfileDir
        $DocsPath = Expand-UserPath $UShell.Personal -UserProfileDir $ProfileDir
        $PicturesPath = Expand-UserPath $UShell.'My Pictures' -UserProfileDir $ProfileDir
        if (-not $DesktopPath) { $DesktopPath = Join-Path $ProfileDir 'Desktop' }
        if (-not $DocsPath) { $DocsPath = Join-Path $ProfileDir 'Documents' }
        if (-not $PicturesPath) { $PicturesPath = Join-Path $ProfileDir 'Pictures' }
    } catch {}
}

# MAP: Backup folder name -> destination path in profile
$ProfileFolderMap = @{
    'Desktop'   = $DesktopPath
    'Documents' = $DocsPath
    'Pictures'  = $PicturesPath
    'Downloads' = Join-Path $ProfileDir 'Downloads'
    'Favorites' = Join-Path $ProfileDir 'Favorites'
    'Music'     = Join-Path $ProfileDir 'Music'
    'Videos'    = Join-Path $ProfileDir 'Videos'
    'Links'     = Join-Path $ProfileDir 'Links'
    'Saved Games' = Join-Path $ProfileDir 'Saved Games'
    'Contacts'  = Join-Path $ProfileDir 'Contacts'
    'Searches'  = Join-Path $ProfileDir 'Searches'
    '3D Objects' = Join-Path $ProfileDir '3D Objects'
    'OneDrive'  = Join-Path $ProfileDir 'OneDrive'
}

$AppFolderMap = @{
    'Outlook' = Join-Path $ProfileDir 'AppData\Roaming\Microsoft\Outlook'
    'Chrome'  = Join-Path $ProfileDir 'AppData\Local\Google\Chrome\User Data'
    'Edge'    = Join-Path $ProfileDir 'AppData\Local\Microsoft\Edge\User Data'
    'Firefox' = Join-Path $ProfileDir 'AppData\Roaming\Mozilla'
}

$SkipFolders = @('Printers')
$SkipFiles = @('BackupSummary.txt', 'BACKUP_COMPLETED.txt', 'RESTORE_PrinterConfig.txt', 'RESTORE_COMPLETED.txt')

# SCAN BACKUP - restore whatever exists
Write-Host "Scanning backup for items to restore..."
$BackedUpItems = Get-ChildItem $BackupRoot -Directory -ErrorAction SilentlyContinue | Where-Object {
    $_.Name -notin $SkipFolders
}

foreach ($Item in $BackedUpItems) {
    $Name = $Item.Name
    $Src = $Item.FullName

    if ($ProfileFolderMap.ContainsKey($Name)) {
        $Dest = $ProfileFolderMap[$Name]
        Write-Host "Restoring $Name -> $Dest"
        try { Invoke-RoboRestore -Source $Src -Destination $Dest } catch { Write-Warning $_.Exception.Message }
    }
    elseif ($AppFolderMap.ContainsKey($Name)) {
        $Dest = $AppFolderMap[$Name]
        Write-Host "Restoring $Name -> $Dest"
        try { Invoke-RoboRestore -Source $Src -Destination $Dest } catch { Write-Warning $_.Exception.Message }
    }
    else {
        $Dest = Join-Path $ProfileDir $Name
        Write-Host "Restoring $Name -> $Dest (direct profile folder)"
        try { Invoke-RoboRestore -Source $Src -Destination $Dest } catch { Write-Warning $_.Exception.Message }
    }
}

# PRINTERS - full restore using PrintBrm (if .printerExport exists)
$PrinterDir = Join-Path $BackupRoot "Printers"
$PrintBrmExport = Join-Path $PrinterDir "Printers.printerExport"
$PrinterJson = Join-Path $PrinterDir "Printers.json"
if (Test-Path $PrintBrmExport) {
    Write-Host "Restoring printers (PrintBrm)..."
    $PrintBrmPath = Join-Path $env:SystemRoot "System32\spool\tools\printbrm.exe"
    if (Test-Path $PrintBrmPath) {
        $pinfo = New-Object System.Diagnostics.ProcessStartInfo
        $pinfo.FileName = $PrintBrmPath
        $pinfo.Arguments = "-r -s \\$env:COMPUTERNAME -f `"$PrintBrmExport`" -o force -noacl"
        $pinfo.RedirectStandardError = $true
        $pinfo.RedirectStandardOutput = $true
        $pinfo.UseShellExecute = $false
        $pinfo.CreateNoWindow = $false
        $p = New-Object System.Diagnostics.Process
        $p.StartInfo = $pinfo
        $p.Start() | Out-Null
        $out = $p.StandardOutput.ReadToEnd()
        $err = $p.StandardError.ReadToEnd()
        $p.WaitForExit()
        if ($p.ExitCode -ne 0) {
            Write-Warning "PrintBrm exit code: $($p.ExitCode)"
            if ($err) { Write-Host $err -ForegroundColor Yellow }
            if ($out) { Write-Host $out }
        } else {
            Write-Host "Printers restored successfully." -ForegroundColor Green
        }
    } else {
        Write-Warning "PrintBrm not found at $PrintBrmPath. Cannot restore printers."
    }
} elseif (Test-Path $PrinterJson) {
    Write-Host "Printers.printerExport not found. Attempting restore from Printers.json + Drivers..."
    try {
        Import-Module PrintManagement -ErrorAction Stop
        $Snapshot = Get-Content $PrinterJson -Raw -ErrorAction Stop | ConvertFrom-Json
        $DriversDir = Join-Path $PrinterDir "Drivers"
        $DefaultPrinter = ($Snapshot.Printers | Where-Object { $_.IsDefault -eq $true } | Select-Object -First 1).Name
        $driverFolders = if (Test-Path $DriversDir) { @(Get-ChildItem $DriversDir -Directory -ErrorAction SilentlyContinue) } else { @() }
        if ($driverFolders.Count -eq 0) { Write-Host "  No Drivers folder found - run backup again with Printers checked." -ForegroundColor Yellow }
        foreach ($p in $Snapshot.Printers) {
            $driverName = ($p.DriverName -replace '\s+$','').Trim()
            $portName = $p.PortName
            $printerName = $p.Name
            if (Get-Printer -Name $printerName -ErrorAction SilentlyContinue) { Write-Host "  $printerName already exists."; continue }
            $driverInstalled = Get-PrinterDriver -Name $driverName -ErrorAction SilentlyContinue
            if (-not $driverInstalled -and $driverFolders.Count -gt 0) {
                $driverFolder = $driverFolders | Where-Object { $_.Name -replace '[\\/:*?"<>|]','_' -eq ($driverName -replace '[\\/:*?"<>|]','_') } | Select-Object -First 1
                if (-not $driverFolder) { $driverFolder = $driverFolders | Where-Object { $_.Name -like "*$($driverName.Split(' ')[0])*" } | Select-Object -First 1 }
                if (-not $driverFolder) { $driverFolder = $driverFolders[0] }
                if ($driverFolder) {
                    $infFile = Get-ChildItem $driverFolder.FullName -Filter "*.inf" -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.Name -notmatch '^(oem|pnputil)' } | Select-Object -First 1
                    if (-not $infFile) { $infFile = Get-ChildItem $driverFolder.FullName -Filter "*.inf" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1 }
                    if ($infFile) {
                        Write-Host "  Installing driver for $printerName from $($infFile.Name)..."
                        $pnpresult = & pnputil.exe /add-driver "`"$($infFile.FullName)`"" /install 2>&1
                        if ($LASTEXITCODE -ne 0) {
                            Write-Host "  pnputil: $pnpresult" -ForegroundColor Gray
                            Write-Host "  Trying printui (direct INF install)..."
                            Start-Process -FilePath "rundll32.exe" -ArgumentList "printui.dll,PrintUIEntry /ia /m `"$driverName`" /f `"$($infFile.FullName)`"" -Wait -NoNewWindow
                        } else { Write-Host "  Driver added to store." -ForegroundColor Green }
                    } else { Write-Host "  No .inf found in $($driverFolder.Name)" -ForegroundColor Yellow }
                }
            }
            $portExists = Get-PrinterPort -Name $portName -ErrorAction SilentlyContinue
            if (-not $portExists -and $p.PortAddress) {
                Write-Host "  Adding TCP/IP port $portName -> $($p.PortAddress)..."
                try { Add-PrinterPort -Name $portName -PrinterHostAddress $p.PortAddress } catch { Add-PrinterPort -Name "IP_$($p.PortAddress)" -PrinterHostAddress $p.PortAddress; $portName = "IP_$($p.PortAddress)" }
            }
            $driverNow = Get-PrinterDriver -Name $driverName -ErrorAction SilentlyContinue
            $portNow = Get-PrinterPort -Name $portName -ErrorAction SilentlyContinue
            if ($driverNow -and $portNow) {
                Add-Printer -Name $printerName -DriverName $driverName -PortName $portName -ErrorAction Stop
                Write-Host "  Added printer: $printerName" -ForegroundColor Green
                if ($printerName -eq $DefaultPrinter) { try { (Get-WmiObject -Query "SELECT * FROM Win32_Printer WHERE Name='$($printerName -replace "'","''")'").SetDefaultPrinter() | Out-Null } catch {} }
            } else {
                $why = @()
                if (-not $driverNow) { $why += "driver '$driverName' not installed" }
                if (-not $portNow) { $why += "port '$portName' missing" }
                Write-Warning "  Could not add $printerName - $($why -join '; ')."
                Write-Host "    Driver folders: $($driverFolders.Name -join ', ')" -ForegroundColor Gray
                Write-Host "    Install driver from: $DriversDir" -ForegroundColor Gray
            }
        }
    } catch { Write-Warning "Printer restore from JSON failed: $($_.Exception.Message)" }
}
if (Test-Path $PrinterJson) {
    try {
        $Snapshot = Get-Content $PrinterJson -Raw -ErrorAction Stop | ConvertFrom-Json
        $Snapshot | ConvertTo-Json -Depth 4 | Out-File (Join-Path $BackupRoot "RESTORE_PrinterConfig.txt") -Encoding UTF8 -ErrorAction SilentlyContinue
    } catch {}
}

# COMPLETE
$Summary = "RESTORE COMPLETED`nSource: $BackupRoot`nTarget: $ProfileDir`nCompleted: $(Get-Date)"
$Summary | Out-File (Join-Path $BackupRoot "RESTORE_COMPLETED.txt") -Encoding UTF8 -Append -ErrorAction SilentlyContinue
Write-Host "=== DOMAIN MIGRATION RESTORE COMPLETED ===" -ForegroundColor Green
Read-Host "`nPress Enter to close"
